import os,json,subprocess,tempfile,hashlib,datetime
repo=r'E:\WebAIBridge'
sha='9a8898a70355bbae2d465ee49739030aa27e9f4e'
branch='agent/bridge-r44-hotfix-r43-integration-20261007'
expected='ca53b0e3a8e1e11ca48e162b72be4ca983e378a3'
def git(*args):
 return subprocess.run(['git.exe','-C',repo,*args],capture_output=True,timeout=15)
def fingerprint():
 h=git('rev-parse','HEAD')
 s=git('status','--porcelain=v1','-z','--untracked-files=all')
 return {'head':h.stdout.decode('ascii','replace').strip(),'status_sha256':hashlib.sha256(s.stdout).hexdigest(),'status_count':len([x for x in s.stdout.split(b'\0') if x]),'git_codes':[h.returncode,s.returncode]}
out={'at':datetime.datetime.now().isoformat(),'target':sha,'before':fingerprint()}
try:
 b=git('cat-file','blob',sha+':app/r42-cutover.ps1')
 if b.returncode:raise RuntimeError('target cutover git blob unavailable')
 with tempfile.TemporaryDirectory(prefix='r44-staged-preflight-') as d:
  staged=os.path.join(d,'r42-cutover.ps1')
  with open(staged,'wb') as f:f.write(b.stdout)
  blob_check=subprocess.run(['git.exe','hash-object','--no-filters',staged],capture_output=True,text=True,timeout=12)
  observed=blob_check.stdout.strip()
  out['verified_blob']=observed==expected
  if observed!=expected:raise RuntimeError('source blob SHA mismatch')
  cmd=['powershell.exe','-NoProfile','-ExecutionPolicy','Bypass','-File',staged,'-TargetSha',sha,'-TargetBranch',branch,'-RepoPath',repo,'-PreflightOnly']
  run=subprocess.run(cmd,capture_output=True,text=True,errors='replace',timeout=95)
  out['preflight']={'exit_code':run.returncode,'stdout':run.stdout.strip()[-6500:],'stderr':run.stderr.strip()[-2600:]}
except Exception as e:out['error']=type(e).__name__+': '+str(e)[:400]
out['after']=fingerprint()
out['worktree_unchanged']=out['before']==out['after']
print(json.dumps(out,ensure_ascii=True,default=str))
